'use client';

import { Swap as SwapPrimitive, useSwap, useSwapContext } from '@ark-ui/react/swap';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { normalizeClassName } from '@/lib/moduix/normalizeClassName';
import styles from './Swap.module.css';

type SwapAnimation = 'fade' | 'scale' | 'rotate' | 'flip' | (string & {});

type SwapRootProps = ComponentProps<typeof SwapPrimitive.Root> & {
  animation?: SwapAnimation;
};

type SwapRootProviderProps = ComponentProps<typeof SwapPrimitive.RootProvider> & {
  animation?: SwapAnimation;
};

const SwapRoot = forwardRef<ComponentRef<typeof SwapPrimitive.Root>, SwapRootProps>(
  function SwapRoot({ animation = 'scale', className, ...props }, ref) {
    return (
      <SwapPrimitive.Root
        ref={ref}
        data-slot="swap-root"
        data-animation={animation}
        className={clsx(styles.root, normalizeClassName(className))}
        {...props}
      />
    );
  },
);

const SwapRootProvider = forwardRef<
  ComponentRef<typeof SwapPrimitive.RootProvider>,
  SwapRootProviderProps
>(function SwapRootProvider({ animation = 'scale', className, ...props }, ref) {
  return (
    <SwapPrimitive.RootProvider
      ref={ref}
      data-slot="swap-root-provider"
      data-animation={animation}
      className={clsx(styles.root, normalizeClassName(className))}
      {...props}
    />
  );
});

const SwapIndicator = forwardRef<
  ComponentRef<typeof SwapPrimitive.Indicator>,
  ComponentProps<typeof SwapPrimitive.Indicator>
>(function SwapIndicator({ className, ...props }, ref) {
  return (
    <SwapPrimitive.Indicator
      ref={ref}
      data-slot="swap-indicator"
      className={clsx(styles.indicator, normalizeClassName(className))}
      {...props}
    />
  );
});

const Swap = Object.assign(SwapRoot, {
  Root: SwapRoot,
  RootProvider: SwapRootProvider,
  Indicator: SwapIndicator,
  useSwap,
});

export { Swap, useSwap, useSwapContext, type SwapAnimation };

@layer moduix.components {
  .root {
    display: inline-grid;
    grid-template-areas: 'swap';
    place-items: center;
    vertical-align: middle;

    &[data-animation='flip'] {
      perspective: 24rem;
    }
  }

  .indicator {
    display: inline-flex;
    grid-area: swap;
    align-items: center;
    justify-content: center;
    color: inherit;

    .root[data-animation='fade'] &[data-state='open'] {
      animation: swap-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='fade'] &[data-state='closed'] {
      animation: swap-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='scale'] &[data-state='open'] {
      animation: swap-scale-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='scale'] &[data-state='closed'] {
      animation: swap-scale-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='rotate'] &[data-state='open'] {
      animation: swap-rotate-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='rotate'] &[data-state='closed'] {
      animation: swap-rotate-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='flip'] & {
      backface-visibility: hidden;
    }

    .root[data-animation='flip'] &[data-state='open'] {
      animation: swap-flip-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    .root[data-animation='flip'] &[data-state='closed'] {
      animation: swap-flip-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .indicator[data-state] {
      animation-duration: 1ms;
      animation-delay: 0ms;
    }
  }

  @keyframes swap-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
    }
  }

  @keyframes swap-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
    }
  }

  @keyframes swap-scale-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
      transform: scale(var(--moduix-swap-enter-starting-scale, 0.5));
    }
  }

  @keyframes swap-scale-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
      transform: scale(var(--moduix-swap-exit-ending-scale, 0.5));
    }
  }

  @keyframes swap-rotate-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
      transform: rotate(-180deg);
    }
  }

  @keyframes swap-rotate-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
      transform: rotate(180deg);
    }
  }

  @keyframes swap-flip-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
      transform: rotateY(-180deg);
    }
  }

  @keyframes swap-flip-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
      transform: rotateY(180deg);
    }
  }
}
